CREATE TABLE mem_level (id BIGINT AUTO_INCREMENT PRIMARY KEY, public_id VARCHAR(36) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL UNIQUE,level_rank INT NOT NULL,benefits VARCHAR(4000) NOT NULL,enabled BOOLEAN NOT NULL,version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE mem_member (id BIGINT AUTO_INCREMENT PRIMARY KEY,public_id VARCHAR(36) NOT NULL UNIQUE,customer_public_id VARCHAR(36) NOT NULL UNIQUE,level_public_id VARCHAR(36) NOT NULL,version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(level_public_id) REFERENCES mem_level(public_id));
CREATE TABLE mem_change (id BIGINT AUTO_INCREMENT PRIMARY KEY,public_id VARCHAR(36) NOT NULL UNIQUE,member_public_id VARCHAR(36) NOT NULL,from_level_id VARCHAR(36),to_level_id VARCHAR(36) NOT NULL,reason VARCHAR(1000) NOT NULL,operator_public_id VARCHAR(36) NOT NULL,changed_at TIMESTAMP NOT NULL,FOREIGN KEY(member_public_id) REFERENCES mem_member(public_id));
